from pathlib import Path
import sys
JS='(function(){\'use strict\';\nconst el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n},clone=x=>JSON.parse(JSON.stringify(x)),uid=()=>crypto.randomUUID();\nfunction legacyText(x){return [x.content,...(x.forestNotes?.notes||[]).map(n=>n.text)].filter(Boolean).join(\'\\n\')}\nfunction parse(text){const rows=[];for(const line of String(text||\'\').split(\'\\n\')){if(!line.trim())continue;const parts=line.trim().match(/^(.*?[가-힣ㄱ-ㅎㅏ-ㅣ])\\s+([^가-힣ㄱ-ㅎㅏ-ㅣ\\s].*)$/);const korean=parts?parts[1]:line.trim(),zh=parts?parts[2]:\'\';for(const chunk of korean.split(/[/／]/)){const m=chunk.trim().match(/^([가-힣ㄱ-ㅎㅏ-ㅣ\\s]+)\\s*[=＝→]\\s*([가-힣ㄱ-ㅎㅏ-ㅣ\\s]+)$/);if(!m)return null;rows.push({id:uid(),original:m[1].trim(),spoken:m[2].trim(),zh})}}return rows.length?rows:null}\nconst filled=r=>r.original||r.spoken||r.zh;\nfunction mount(card,x){if(x.kind!==\'colloquial\')return;const state=clone(x.colloquialRows||[]),host=el(\'section\',\'bcol-editor\');card.append(host);const old=card.querySelector(\'[data-tip-field="content"]\')?.closest(\'label\');if(old)old.hidden=true;\nhost.append(el(\'p\',\'bcol-help\',\'把完整說法和口語縮略分開填寫；下方可再加多組。\'));\nconst legacy=legacyText(x);if(legacy){const details=el(\'details\',\'bcol-legacy\');details.append(el(\'summary\',\'\',\'原有筆記（保留）\'));details.append(el(\'div\',\'bcol-text\',legacy));const parsed=parse(legacy);if(parsed&&!state.length){const convert=el(\'button\',\'ghost\',\'將原筆記帶入對照\');convert.type=\'button\';convert.onclick=()=>{state.push(...parsed);convert.remove();render();changed()};details.append(convert);details.open=true}host.append(details)}\nconst list=el(\'div\',\'bcol-list\');host.append(list);const changed=()=>card.dispatchEvent(new Event(\'input\',{bubbles:true}));\nfunction field(label,value,record,key){const wrap=el(\'label\',\'bcol-field\');wrap.append(el(\'span\',\'\',label));const input=el(\'textarea\',\'bcol-input\');input.rows=1;input.value=value||\'\';input.setAttribute(\'aria-label\',label);if(key!==\'zh\')input.lang=\'ko\';else input.lang=\'zh-Hant\';wrap.append(input);input.oninput=()=>{record[key]=input.value;changed()};if(window.banaTipTextColors)banaTipTextColors.mount(input,record[key+\'Highlights\']||[]);return wrap}\nfunction collect(){for(const row of list.children){const record=state.find(r=>r.id===row.dataset.id);for(const [i,key]of [\'original\',\'spoken\',\'zh\'].entries()){const input=row.querySelectorAll(\'textarea\')[i];record[key]=input.value;if(window.banaTipTextColors)record[key+\'Highlights\']=banaTipTextColors.collect(input)}}return clone(state)}\nfunction render(){list.replaceChildren();state.forEach((r,i)=>{r.id=r.id||uid();const row=el(\'section\',\'bcol-row\');row.dataset.id=r.id;const head=el(\'header\',\'bcol-head\');head.append(el(\'b\',\'\',\'口語變化 \'+String(i+1).padStart(2,\'0\')));const ops=el(\'div\',\'bcol-ops\');for(const [label,delta]of [[\'↑\',-1],[\'↓\',1]]){const b=el(\'button\',\'ghost\',label);b.type=\'button\';b.disabled=i+delta<0||i+delta>=state.length;b.setAttribute(\'aria-label\',delta<0?\'上移口語變化\':\'下移口語變化\');b.onclick=()=>{collect();[state[i],state[i+delta]]=[state[i+delta],state[i]];render();changed()};ops.append(b)}const remove=el(\'button\',\'ghost\',\'刪除\');remove.type=\'button\';remove.onclick=()=>{collect();if(filled(r)&&!confirm(\'刪除這組口語變化？\'))return;state.splice(i,1);render();changed()};ops.append(remove);head.append(ops);const grid=el(\'div\',\'bcol-grid\');grid.append(field(\'完整說法\',r.original,r,\'original\'),el(\'span\',\'bcol-arrow\',\'→\'),field(\'口語說法\',r.spoken,r,\'spoken\'));row.append(head,grid,field(\'中文意思（選填）\',r.zh,r,\'zh\'));list.append(row)})}\nconst add=el(\'button\',\'ghost\',\'＋ 新增一組口語變化\');add.type=\'button\';add.onclick=()=>{collect();state.push({id:uid(),original:\'\',spoken:\'\',zh:\'\'});render();changed();list.lastElementChild.querySelector(\'textarea\').banaColorEditor?.focus()};host.append(add);card.collectColloquialRows=collect;render();}\nconst esc=s=>String(s||\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c])),rich=(s,h)=>window.banaTipTextColors?banaTipTextColors.html(s||\'\',h||[]):esc(s);\nconst previous=window.banaGrammarTipsHtml;window.banaGrammarTipsHtml=function(g){const t=document.createElement(\'template\');t.innerHTML=previous(g);const notes=banaGrammarTipModel.clean(banaGrammarTipModel.fromLegacy(g));[...t.content.querySelectorAll(\'.bgt-read-card\')].forEach((card,i)=>{const x=notes[i];if(x?.kind!==\'colloquial\')return;const rows=(x.colloquialRows||[]).filter(filled);card.classList.add(\'bcol-reading\');card.innerHTML=\'<h4>\'+esc(x.title||\'口語變化\')+\'</h4>\'+rows.map(r=>\'<section class="bcol-read-row"><div class="bcol-grid"><div><small>完整說法</small><p lang="ko">\'+rich(r.original,r.originalHighlights)+\'</p></div><span class="bcol-arrow" aria-label="變成">→</span><div><small>口語說法</small><p lang="ko">\'+rich(r.spoken,r.spokenHighlights)+\'</p></div></div>\'+(r.zh?\'<p class="bcol-zh" lang="zh-Hant">\'+rich(r.zh,r.zhHighlights)+\'</p>\':\'\')+\'</section>\').join(\'\');if(!rows.length){const old=el(\'div\',\'bcol-text\',legacyText(x));card.append(old)}});return t.innerHTML};\nwindow.banaColloquialNotes={mount,parse};\n})();\n'
CSS='.bcol-editor,.bcol-reading{width:100%;min-width:0;box-sizing:border-box}.bcol-help{margin:6px 0;color:#7c896e;line-height:1.5}.bcol-list{display:grid;gap:8px;margin:8px 0}.bcol-row,.bcol-read-row{padding:9px;border:1px solid #dce3d3;border-radius:10px;background:#f0f5eb;min-width:0}.bcol-row:nth-child(even),.bcol-read-row:nth-child(even){background:#f8f3ec}.bcol-head{display:flex;align-items:center;justify-content:space-between;gap:5px;margin-bottom:5px}.bcol-ops{display:flex;gap:3px}.bcol-grid{display:grid;grid-template-columns:minmax(0,1fr) 18px minmax(0,1fr);gap:5px;align-items:start}.bcol-arrow{align-self:center;text-align:center;color:#839a6c}.bcol-field{display:block;min-width:0;margin:3px 0}.bcol-field>span,.bcol-grid small{display:block;color:#829275;font-size:12px;margin-bottom:3px}.bcol-input{box-sizing:border-box;width:100%;min-height:38px;resize:vertical;border:1px solid #d7e0cd;border-radius:7px;padding:6px;background:#fffefb;font:inherit;color:#405b3c}.bcol-field [contenteditable]{min-height:36px!important;white-space:pre-wrap}.bcol-editor>.ghost{width:100%}.bcol-legacy{margin:6px 0;color:#829275}.bcol-text{white-space:pre-wrap;overflow-wrap:anywhere}.bcol-read-row{margin-top:6px}.bcol-read-row p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5}.bcol-read-row .bcol-zh{margin:3px 0 0;color:#95826d}.bcol-reading h4{margin:0 0 6px}.bcol-field .btc-toolbar{flex-wrap:wrap;gap:2px}.bcol-field .btc-toolbar small{display:none}.bcol-grid .bcol-field .brc-swatch{width:19px!important;height:19px!important;min-height:19px!important;min-width:19px!important;padding:0!important}.bcol-editor [hidden]{display:none!important}\n'
def apply(path):
 p=Path(path);s=p.read_text(encoding='utf-8')
 if 'id="bana-colloquial-notes"' in s:return
 changes=[
 ("phonetics:'發音規則整理',extra:","phonetics:'發音規則整理',colloquial:'口語變化',extra:"),
 ("if(card.collectForestNotes)x.forestNotes=card.collectForestNotes();","if(card.collectForestNotes)x.forestNotes=card.collectForestNotes();if(card.collectColloquialRows)x.colloquialRows=card.collectColloquialRows();"),
 ("window.banaForestNotes?.mountTip(card,rows[i]);","window.banaForestNotes?.mountTip(card,rows[i]);window.banaColloquialNotes?.mount(card,rows[i]);"),
 ("||x.noteBlocks?.length||x.forestNotes", "||x.noteBlocks?.length||x.colloquialRows?.some(r=>r.original||r.spoken||r.zh)||x.forestNotes")]
 for old,new in changes:
  if s.count(old)!=1:raise ValueError('Expected unique integration point: '+old)
  s=s.replace(old,new,1)
 s=s.replace('</head>','<style id="bana-colloquial-style">'+CSS+'</style>\n</head>',1)
 s=s.replace('</body>','<script id="bana-colloquial-notes">'+JS+'</script>\n</body>',1)
 p.write_bytes(s.encode('utf-8'))
if __name__=='__main__':apply(sys.argv[1] if len(sys.argv)>1 else 'index.html')
